import { Link } from "@tanstack/react-router";
import { heroClassLabel, getPublicStrings } from "@/lib/cms/public-strings";
import type { PublicHeroItem } from "@/lib/cms/public.loader";

export function heroDetailHref(locale: string, slug: string): string {
  return locale === "en" ? `/heroes/${slug}` : `/${locale}/heroes/${slug}`;
}
export function loadoutDetailHref(locale: string, slug: string): string {
  return locale === "en" ? `/loadouts/${slug}` : `/${locale}/loadouts/${slug}`;
}

export function HeroCard({
  hero,
  locale,
  onPreview,
}: {
  hero: PublicHeroItem;
  locale: string;
  onPreview?: (hero: PublicHeroItem) => void;
}) {
  const s = getPublicStrings(locale);
  return (
    <article
      className="overflow-hidden rounded-xl border border-panel-border bg-background/40 transition-all hover:-translate-y-0.5 hover:border-primary"
      data-testid="hero-card"
    >
      {hero.imageUrl ? (
        <img
          src={hero.imageUrl}
          alt={hero.title}
          className="aspect-[4/3] w-full object-cover"
          loading="lazy"
        />
      ) : (
        <div
          className="grid aspect-[4/3] w-full place-items-center bg-muted text-4xl"
          aria-hidden="true"
        >
          ≡ƒ¢í∩╕Å
        </div>
      )}
      <div className="p-4">
        <h3 className="font-display text-base font-bold">
          <Link
            to={heroDetailHref(locale, hero.slug)}
            className="rounded outline-none focus-visible:ring-2 focus-visible:ring-ring hover:text-primary"
          >
            {hero.title}
          </Link>
        </h3>
        <p className="mt-1 text-xs uppercase tracking-wider text-muted-foreground">
          {s.classNameLabel}: {heroClassLabel(locale, hero.heroClass)}
          {hero.category ? ` ┬╖ ${hero.category}` : ""}
        </p>
        {hero.description ? (
          <p className="mt-2 line-clamp-2 text-sm text-muted-foreground">
            {hero.description.slice(0, 140)}
          </p>
        ) : null}
        <div className="mt-3 flex gap-2">
          <Link
            to={heroDetailHref(locale, hero.slug)}
            className="rounded-lg bg-primary px-3 py-1.5 text-xs font-bold text-primary-foreground"
          >
            {s.viewDetails}
          </Link>
          {onPreview ? (
            <button
              type="button"
              onClick={() => onPreview(hero)}
              className="rounded-lg border border-panel-border px-3 py-1.5 text-xs font-semibold hover:border-primary"
              aria-haspopup="dialog"
            >
              {s.openPreview}
            </button>
          ) : null}
        </div>
      </div>
    </article>
  );
}

import * as React from "react";
import { Link } from "@tanstack/react-router";
import { getPublicStrings, heroClassLabel } from "@/lib/cms/public-strings";
import type { PublicHeroDetail } from "@/lib/cms/public-hero-detail.loader";
import { heroDetailHref } from "./HeroCard";
import { loadoutDetailHref } from "./LoadoutCard";

export function HeroDetail({
  hero,
  locale,
  backHref,
}: {
  hero: PublicHeroDetail;
  locale: string;
  backHref: string;
}) {
  const s = getPublicStrings(locale);
  return (
    <main className="mx-auto max-w-4xl px-4 py-10">
      <Link to={backHref} className="text-sm underline">
        ΓåÉ {s.backToHeroes}
      </Link>
      <h1 className="mt-3 font-display text-3xl font-extrabold">{hero.title}</h1>
      <p className="mt-1 text-xs uppercase tracking-wider text-muted-foreground">
        {s.classNameLabel}: {heroClassLabel(locale, hero.heroClass)}
        {hero.category ? ` ┬╖ ${s.categoryLabel}: ${hero.category}` : ""}
      </p>
      {hero.imageUrl ? (
        <img src={hero.imageUrl} alt={hero.title} className="mt-4 w-full rounded-xl object-cover" />
      ) : null}
      {hero.description ? <p className="mt-4 leading-relaxed">{hero.description}</p> : null}
      {hero.abilities.length > 0 ? (
        <section className="mt-8" aria-label={s.abilities}>
          <h2 className="font-display text-xl font-bold">{s.abilities}</h2>
          <ul className="mt-3 space-y-3">
            {hero.abilities.map((a) => (
              <li key={a.key} className="rounded-xl border border-panel-border p-4">
                <h3 className="font-bold">{a.name}</h3>
                {a.description ? (
                  <p className="mt-1 text-sm text-muted-foreground">{a.description}</p>
                ) : null}
              </li>
            ))}
          </ul>
        </section>
      ) : null}
      {hero.relatedLoadouts.length > 0 ? (
        <section className="mt-8" aria-label={s.relatedLoadouts}>
          <h2 className="font-display text-xl font-bold">{s.relatedLoadouts}</h2>
          <ul className="mt-3 grid gap-3 sm:grid-cols-2">
            {hero.relatedLoadouts.map((l) => (
              <li key={l.contentId} className="rounded-xl border border-panel-border p-4">
                <Link
                  to={loadoutDetailHref(locale, l.slug)}
                  className="font-bold hover:text-primary"
                >
                  {l.title}
                </Link>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
      <p className="mt-8 text-xs text-muted-foreground">{heroDetailHref(locale, hero.slug)}</p>
    </main>
  );
}
export function useX(): null {
  return React.useMemo(() => null, []);
}

import * as React from "react";
import { Link } from "@tanstack/react-router";
import { Dialog, DialogContent, DialogDescription, DialogTitle } from "@/components/ui/dialog";
import { getPublicStrings, heroClassLabel } from "@/lib/cms/public-strings";
import type { PublicHeroItem } from "@/lib/cms/public.loader";
import { heroDetailHref } from "./HeroCard";

/** Large modal/tour enhancement: canonical route remains the source of truth. */
export function HeroPreviewDialog({
  hero,
  locale,
  onClose,
}: {
  hero: PublicHeroItem | null;
  locale: string;
  onClose: () => void;
}) {
  const s = getPublicStrings(locale);
  const open = hero !== null;
  return (
    <Dialog
      open={open}
      onOpenChange={(v) => {
        if (!v) onClose();
      }}
    >
      <DialogContent className="max-w-2xl" aria-describedby={undefined}>
        {hero ? (
          <div data-testid="hero-preview-dialog">
            <DialogTitle>{hero.title}</DialogTitle>
            <DialogDescription>
              {s.classNameLabel}: {heroClassLabel(locale, hero.heroClass)}
            </DialogDescription>
            {hero.imageUrl ? (
              <img
                src={hero.imageUrl}
                alt={hero.title}
                className="mt-4 max-h-72 w-full rounded-lg object-cover"
              />
            ) : null}
            {hero.description ? (
              <p className="mt-4 text-sm leading-relaxed">{hero.description.slice(0, 600)}</p>
            ) : null}
            <div className="mt-4 flex gap-2">
              <Link
                to={heroDetailHref(locale, hero.slug)}
                className="rounded-lg bg-primary px-4 py-2 text-sm font-bold text-primary-foreground"
              >
                {s.viewDetails}
              </Link>
              <button
                type="button"
                onClick={onClose}
                className="rounded-lg border border-panel-border px-4 py-2 text-sm font-semibold"
              >
                {s.close}
              </button>
            </div>
          </div>
        ) : null}
      </DialogContent>
    </Dialog>
  );
}

export function useHeroPreview() {
  const [preview, setPreview] = React.useState<PublicHeroItem | null>(null);
  return { preview, setPreview };
}

import { Link } from "@tanstack/react-router";
import { getPublicStrings } from "@/lib/cms/public-strings";
import type { PublicInventoryItem } from "@/lib/cms/public-inventory.loader";

export function inventoryDetailHref(locale: string, slug: string): string {
  return locale === "en" ? `/inventory/${slug}` : `/${locale}/inventory/${slug}`;
}

/**
 * Phase 15 ΓÇö public Inventory item card.
 * Shows delivery-URL image only (never provider/private media fields),
 * localized name, weapon/trap type + editorial subtype, safe metadata,
 * and a link to the canonical detail page. Logical CSS properties keep
 * RTL correct; artwork itself is never mirrored.
 */
export function InventoryCard({ item, locale }: { item: PublicInventoryItem; locale: string }) {
  const s = getPublicStrings(locale);
  const typeLabel = item.kind === "weapon" ? s.weaponLabel : s.trapLabel;
  const subtype = item.kind === "weapon" ? item.weaponSubtype : item.trapSubtype;
  return (
    <article
      className="overflow-hidden rounded-xl border border-panel-border bg-background/40 transition-all hover:-translate-y-0.5 hover:border-primary"
      data-testid="inventory-card"
      data-kind={item.kind}
    >
      {item.imageUrl ? (
        <img
          src={item.imageUrl}
          alt={item.title}
          className="aspect-[4/3] w-full object-cover"
          loading="lazy"
        />
      ) : (
        <div
          className="grid aspect-[4/3] w-full place-items-center bg-muted text-4xl"
          aria-hidden="true"
        >
          {item.kind === "trap" ? "≡ƒ¬ñ" : "ΓÜö∩╕Å"}
        </div>
      )}
      <div className="p-4">
        <h3 className="font-display text-base font-bold">
          <Link
            to={inventoryDetailHref(locale, item.slug)}
            className="rounded outline-none focus-visible:ring-2 focus-visible:ring-ring hover:text-primary"
          >
            {item.title}
          </Link>
        </h3>
        <p className="mt-1 text-xs uppercase tracking-wider text-muted-foreground">
          {typeLabel}
          {subtype ? ` ┬╖ ${s.subtypeLabel}: ${subtype}` : ""}
        </p>
        {item.description ? (
          <p className="mt-2 line-clamp-2 text-sm text-muted-foreground">
            {item.description.slice(0, 140)}
          </p>
        ) : null}
        <div className="mt-3">
          <Link
            to={inventoryDetailHref(locale, item.slug)}
            className="rounded-lg bg-primary px-3 py-1.5 text-xs font-bold text-primary-foreground"
          >
            {s.viewDetails}
          </Link>
        </div>
      </div>
    </article>
  );
}

