/**
 * Phase 5 ΓÇö i18n React context for HawkBucks.
 *
 * Bridges the Phase 3 language preference (`useLanguagePreference`, the
 * single persistence system ΓÇö cookie-backed, SSR-seeded) to a `t()` function
 * for components. Components consume `useI18n()`; they never touch cookies,
 * dictionaries, or the resolution order directly.
 *
 * Hydration safety: state seeds from the SSR loader value, so server HTML and
 * the first client paint agree. Browser-language detection runs only in a
 * post-hydration effect and only when no explicit saved choice exists
 * (no `hawkbucks_language` cookie) ΓÇö an explicit choice is never overridden.
 * Setting a language persists it via the preference hook, so it survives
 * refresh and takes precedence from then on.
 */

import * as React from "react";

import { useLanguagePreference } from "@/hooks/use-preferences";
import {
  parseLanguage,
  readLanguageFromDocumentCookie,
  type LanguageCode,
} from "@/lib/preferences";
import { getLanguageConfig, type TextDirection } from "./config";
import { resolveClientLanguage, translate } from "./core";
import type { TranslationKey, TranslationParams } from "./types";

export interface I18nContextValue {
  t: (key: TranslationKey, params?: TranslationParams) => string;
  currentLanguage: LanguageCode;
  direction: TextDirection;
  locale: string;
  setLanguage: (code: LanguageCode) => void;
}

const I18nContext = React.createContext<I18nContextValue | null>(null);

export function I18nProvider({
  children,
  initialLanguage,
  fixedLanguage,
}: {
  children: React.ReactNode;
  initialLanguage: LanguageCode;
  /** Phase 6: when set, the provider is pinned to this language (localized routes). */
  fixedLanguage?: LanguageCode | undefined;
}) {
  const { language: storedLanguage, setLanguage } = useLanguagePreference(
    parseLanguage(fixedLanguage ?? initialLanguage),
  );

  const activeLanguage =
    fixedLanguage !== undefined ? parseLanguage(fixedLanguage) : storedLanguage;

  // First-visit browser reconciliation: adopt the browser language only when
  // the user never made an explicit choice (no language cookie). Runs as an
  // effect so SSR and the first paint stay in agreement. Skipped entirely for
  // pinned (localized-route) providers so crawlers without cookies see the
  // URL locale.
  React.useEffect(() => {
    if (fixedLanguage !== undefined) return;
    if (readLanguageFromDocumentCookie() !== undefined) return;
    const detected = resolveClientLanguage(undefined);
    if (detected !== undefined && detected !== activeLanguage) {
      setLanguage(detected);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const config = getLanguageConfig(activeLanguage);

  const t = React.useCallback(
    (key: TranslationKey, params?: TranslationParams) => translate(key, activeLanguage, params),
    [activeLanguage],
  );

  const value = React.useMemo<I18nContextValue>(
    () => ({
      t,
      currentLanguage: activeLanguage,
      direction: config.direction,
      locale: config.locale,
      setLanguage,
    }),
    [t, activeLanguage, config.direction, config.locale, setLanguage],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const ctx = React.useContext(I18nContext);
  if (!ctx) throw new Error("useI18n must be used within I18nProvider.");
  return ctx;
}

// Test-only ESM loader hooks:
// - maps the "@/" tsconfig path alias to src/
// - resolves extensionless relative imports to their .ts files
// - shims import.meta.env for src modules that read VITE_* at module scope
// Used by `npm run test:server` under Node's --experimental-strip-types.
import { existsSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import path from "node:path";

const srcDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "src");
const frontendDir = path.resolve(srcDir, "..");

export async function resolve(specifier, context, nextResolve) {
  const [base, query] = splitQuery(specifier);

  // Test-only mappings for TanStack Start's package import specifiers.
  // These map the package-import-style aliases used at runtime to our local
  // source entry points so Node tests can import them directly.
  if (base === "#tanstack-router-entry") {
    // Prefer the built SSR router module if present (avoids loading .tsx directly).
    const built = path.join(frontendDir, ".output", "server", "_ssr", "router-j_onzWpi.mjs");
    if (existsSync(built)) return nextResolve(pathToFileURL(built).href + query, context);
    return nextResolve(pathToFileURL(path.join(srcDir, "router.tsx")).href + query, context);
  }
  if (base === "#tanstack-start-entry") {
    return nextResolve(pathToFileURL(path.join(srcDir, "start.ts")).href + query, context);
  }
  if (base === "#tanstack-start-plugin-adapters") {
    // Resolve to a tiny test shim next to this hook file.
    const shim = path.join(path.dirname(fileURLToPath(import.meta.url)), "_tanstack-start-plugin-adapters.mjs");
    return nextResolve(pathToFileURL(shim).href + query, context);
  }

  if (base.startsWith("@/")) {
    const candidate = path.join(srcDir, base.slice(2));
    // Extensionless aliased imports (e.g. "@/lib/preferences") resolve to
    // their .ts source, mirroring the relative-import branch below.
    if (!/\.[cm]?[jt]s$/.test(base)) {
      if (existsSync(`${candidate}.ts`)) return nextResolve(pathToFileURL(`${candidate}.ts`).href + query, context);
      if (existsSync(`${candidate}.tsx`)) return nextResolve(pathToFileURL(`${candidate}.tsx`).href + query, context);
    }
    return nextResolve(pathToFileURL(candidate).href + query, context);
  }

  const isRelative = base.startsWith("./") || base.startsWith("../");
  const hasExtension = /\.[cm]?[jt]s$/.test(base) || base.endsWith('.tsx');
  if (isRelative && !hasExtension && context.parentURL?.startsWith(pathToFileURL(srcDir).href)) {
    const tryTs = new URL(`${base}.ts`, context.parentURL);
    if (existsSync(fileURLToPath(tryTs))) return nextResolve(tryTs.href + query, context);
    const tryTsx = new URL(`${base}.tsx`, context.parentURL);
    if (existsSync(fileURLToPath(tryTsx))) return nextResolve(tryTsx.href + query, context);
  }

  return nextResolve(specifier, context);
}

function splitQuery(specifier) {
  const index = specifier.indexOf("?");
  if (index === -1) return [specifier, ""];
  return [specifier.slice(0, index), specifier.slice(index)];
}

export async function load(url, context, nextLoad) {
  const result = await nextLoad(url, context);
  const [base] = splitQuery(url);
  if (base.startsWith(pathToFileURL(srcDir).href) && (base.endsWith(".ts") || base.endsWith('.tsx'))) {
    // Shim import.meta.env for src modules that may read VITE_* variables at
    // module scope when imported outside Vite.
    result.source = `if (!import.meta.env) import.meta.env = {};\n${result.source}`;
  }
  return result;
}
